pub(super) fn test_aarch64_neon_vst1q_u32() -> Result<(), String> {
    unsafe {
        let mut ptr_ptr = crate::cpu::common::Aligned64([1u32; 16]);
        let a = create_uint32x4_t_from([2, 3, 4, 5]);
        vst1q_u32(ptr_ptr.0.as_mut_ptr(), a);
    }
    Ok(())
}

